            q = deque([(r, c)])
            seen0.add((r, c))
            cells = set()
            edge = False
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny, nx) not in seen0:
                        seen0.add((ny, nx))
                        q.append((ny, nx))
            if not edge:
                cavities.append(cells)

    all_cavities = set().union(*cavities) if cavities else set()
    object_ones = set()
    for cavity in cavities:
        seeds = set()
        # The one-cell inner 4-neighbor ring is 3; the cavity core remains 0.
        for r, c in cavity:
